out = src
for en, ua in P:
    n = out.count(en)
    if n < 1:
        sys.exit("NOT FOUND in index.html: " + en[:90])
    out = out.replace(en, ua)
# paths: the page lives one level deeper
out = out.replace('assets/', '../assets/').replace('"release.json"', '"../release.json"')
out = out.replace('href="https://tak0dan.github.io/sunshineos-site/uk/"', 'href="https://tak0dan.github.io/sunshineos-site/uk/"')
